-- On-chain hedge attestations: the snapshots the service asked the
-- HedgeAttestor contract to record, with what opens each treasury commitment,
-- and one more kind of service key, the attester. Generated by drizzle-kit
-- from src/schema.ts and then made safe to run again.
CREATE TABLE IF NOT EXISTS "holdfast"."attestations" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" text NOT NULL,
	"series" numeric(78, 0) NOT NULL,
	"number" numeric(78, 0),
	"tx" text,
	"journal_count" numeric(78, 0) NOT NULL,
	"journal_root" text NOT NULL,
	"treasury_zat" bigint,
	"salt_enc" text,
	"commitment" text,
	"sent_at" timestamp with time zone NOT NULL,
	"status" text NOT NULL,
	"detail" text,
	CONSTRAINT "attestations_tx_key" UNIQUE("org_id","tx"),
	CONSTRAINT "attestations_snapshot_key" UNIQUE("org_id","series","number"),
	CONSTRAINT "attestations_status_is_known" CHECK ("holdfast"."attestations"."status" in ('pending', 'confirmed', 'reverted', 'refused', 'lost')),
	CONSTRAINT "attestations_sent_has_commitment" CHECK ("holdfast"."attestations"."tx" is null or ("holdfast"."attestations"."treasury_zat" is not null and "holdfast"."attestations"."salt_enc" is not null and "holdfast"."attestations"."commitment" is not null)),
	CONSTRAINT "attestations_number_is_confirmed" CHECK (("holdfast"."attestations"."number" is not null) = ("holdfast"."attestations"."status" = 'confirmed'))
);
--> statement-breakpoint
ALTER TABLE "holdfast"."attestations" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
DO $$ BEGIN
	ALTER TABLE "holdfast"."attestations" ADD CONSTRAINT "attestations_org_id_orgs_id_fk" FOREIGN KEY ("org_id") REFERENCES "holdfast"."orgs"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION
	WHEN duplicate_object THEN NULL;
END $$;
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "attestations_org_idx" ON "holdfast"."attestations" USING btree ("org_id","sent_at");
--> statement-breakpoint
-- At most one attestation of an organisation is pending at a time. A second
-- one cannot be written down, and what is not written down is not sent.
CREATE UNIQUE INDEX IF NOT EXISTS "attestations_pending_key" ON "holdfast"."attestations" USING btree ("org_id") WHERE "holdfast"."attestations"."status" = 'pending';
--> statement-breakpoint
-- The kinds of key a row may hold are a check on the table, so a new kind
-- means a new check. Every key stored so far is of a kind the new one allows.
ALTER TABLE "holdfast"."keys" DROP CONSTRAINT IF EXISTS "keys_kind_is_known";
--> statement-breakpoint
ALTER TABLE "holdfast"."keys" ADD CONSTRAINT "keys_kind_is_known" CHECK ("holdfast"."keys"."kind" in ('hl_agent', 'tempo_access', 'tempo_sponsor', 'solana_delegate', 'hl_attester'));
